import 'dart:convert';
import 'dart:io';

import 'package:open_memex_app/src/db.dart';
import 'package:sqlite3/sqlite3.dart';

/// Path of the V5 schema fixture generated by #3's
/// `crates/memex-core/tests/schema_dump.rs`. Never edit it by hand.
/// `flutter test` runs with the package root (`app/`) as cwd.
const vaultSchemaV5FixturePath = 'test/fixtures/vault_schema_v5.sql';

/// Tables that schema V5 adds (absent from a V4 vault).
const v5Tables = <String>[
  'blocks',
  'day_reviews',
  'day_review_blocks',
  'footer_chips',
  'agent_changes',
  'smart_folders',
  'smart_folder_members',
  'vault_settings',
];

/// A real [VaultDb] over an in-memory SQLite database loaded from the V5
/// schema fixture (D20). Use it as the `vaultDbProvider` override; later WIs
/// add seed helpers as extensions in `test/support/<area>_*.dart`.
class FakeVaultDb extends VaultDb {
  FakeVaultDb._(super.db) : super.fromDatabase();

  /// A fresh V5 vault (the default).
  factory FakeVaultDb() => FakeVaultDb.v5();

  /// A fresh V5 vault: every fixture statement applied.
  factory FakeVaultDb.v5() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    return FakeVaultDb._(db);
  }

  /// A V4 vault: the V5 fixture with the V5-only tables, the V5 index on
  /// `notes` and the `schema_version` row 5 removed, so `MAX(version) = 4`.
  /// [migrateToV5] simulates the CLI's migration on the same handle.
  factory FakeVaultDb.v4() {
    final db = sqlite3.openInMemory();
    db.execute(_fixtureSql());
    db.execute('DROP INDEX IF EXISTS idx_notes_daily_title');
    for (final t in v5Tables) {
      db.execute('DROP TABLE IF EXISTS $t');
    }
    db.execute('DELETE FROM schema_version WHERE version >= 5');
    return FakeVaultDb._(db);
  }

  /// What `memex settings get` does to a V4 vault: replay the V5 fixture
  /// idempotently on this same database handle (the app's handle stays open
  /// while the CLI migrates, as in production).
  void migrateToV5() {
    for (final stmt in _fixtureStatements()) {
      final idempotent = stmt
          .replaceFirst(
            RegExp(r'^CREATE TABLE ', multiLine: false),
            'CREATE TABLE IF NOT EXISTS ',
          )
          .replaceFirst(
            RegExp(r'^CREATE UNIQUE INDEX '),
            'CREATE UNIQUE INDEX IF NOT EXISTS ',
          )
          .replaceFirst(
            RegExp(r'^CREATE INDEX '),
            'CREATE INDEX IF NOT EXISTS ',
          )
          .replaceFirst(RegExp(r'^INSERT INTO '), 'INSERT OR IGNORE INTO ');
      db.execute(idempotent);
    }
  }

  /// `MAX(schema_version.version)`, for test assertions.
  int get schemaVersionForTest =>
      (db.select('SELECT MAX(version) AS v FROM schema_version').first['v']
              as num)
          .toInt();

  /// Record [version] as applied (e.g. 6, a vault newer than this app).
  void addSchemaVersion(int version) {
    db.execute('INSERT OR IGNORE INTO schema_version(version) VALUES (?)', [
      version,
    ]);
  }

  /// Insert one row into `notes`. [role] is a shortcut for
  /// `frontmatter: '{"role":"<role>"}'`; an explicit [frontmatter] wins.
  /// Timestamps are unix ms. Returns [id].
  String seedNote({
    required String id,
    required String title,
    String content = '',
    String? frontmatter,
    String? role,
    int version = 1,
    int createdAt = 1759500000000,
    int? updatedAt,
    List<String> tags = const [],
  }) {
    final fm =
        frontmatter ?? (role == null ? '{}' : jsonEncode({'role': role}));
    db.execute(
      'INSERT INTO notes (id, title, content_md, frontmatter, version, '
      'created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)',
      [id, title, content, fm, version, createdAt, updatedAt ?? createdAt],
    );
    for (final tag in tags) {
      db.execute('INSERT INTO tags (note_id, tag) VALUES (?, ?)', [id, tag]);
    }
    return id;
  }

  static String? _cachedSql;

  static String _fixtureSql() =>
      _cachedSql ??= File(vaultSchemaV5FixturePath).readAsStringSync();

  /// The fixture split into statements (each ends with `;` at a line end).
  static List<String> _fixtureStatements() {
    final withoutComments = _fixtureSql()
        .split('\n')
        .where((l) => !l.trimLeft().startsWith('--'))
        .join('\n');
    return withoutComments
        .split(RegExp(r';\s*\n'))
        .map((s) => s.trim())
        .where((s) => s.isNotEmpty)
        .toList();
  }
}
